// Get the first input item (from webhook)
const input = items[0].json.body || items[0].json;

// Extract order-level data
const orderId = input.orderId;
const orderNumber = parseInt(orderId.replace(/\\D/g, ''), 10);
const uniqueOrderRecordId = input.uniqueOrderRecordId;
const orderedBy = input.orderedBy;
const deliveryParty = input.deliveryParty;
const dateOrdered = input.dateOrdered;
const pickedAt = input.metadata?.pickedAt;
const pickerEmail = input.metadata?.pickerEmail;

// Normalize stock availability values for Supabase
const normalizeStockAvailability = (value) => {
  if (!value) return null;
  const lower = value.toLowerCase().trim();
  if (lower === 'in stock') return 'Available';
  if (lower === 'out of stock') return 'Not Available';
  return value;
};

// Normalize pick status values for Supabase
const normalizePickStatus = (value) => {
  if (!value) return 'Pending';
  const lower = value.toLowerCase().trim();
  if (lower === 'picked in full') return 'Picked';
  if (lower === 'partially picked') return 'Partially Picked';
  if (lower === 'not picked') return 'Not Picked';
  return value;
};

// Map pickedItems to separate line items
const output = input.pickedItems.map((line, index) => {
  return {
    json: {
      lineNumber: index + 1,
      orderId: orderId,
      orderNumber: orderNumber,
      uniqueOrderRecordId: uniqueOrderRecordId,
      orderedBy: orderedBy,
      deliveryParty: deliveryParty,
      dateOrdered: dateOrdered,
      pickedAt: pickedAt,
      pickerEmail: pickerEmail,
      stockOrderId: line.stockOrderId,
      deviceType: line.deviceType,
      quantity: line.quantity,
      stockAvailability: normalizeStockAvailability(line.stockAvailability),
      pickStatus: normalizePickStatus(line.pickStatus),
      packer: line.packer,
      terminalSerialNumber: line.terminalSerialNumber,
      cradleSerialNumber: line.cradleSerialNumber,
      chargerSerialNumber: line.chargerSerialNumber,
      cashConnectSerialNumber: line.cashConnectSerialNumber,
      chargerPacked: line.chargerPacked,
      cables: line.cables,
      itemCode: line.itemCode,
      itemDescription: line.itemDescription
    }
  };
});

return output;
